INSERT INTO GATE_RETRY_QUEUE (ID, ORDER_NO, TXN_DATE, THIRD_USER_ID, CARD_ID, STATUS, RETRY_COUNT, MAX_RETRIES, CREATE_TIME, UPDATE_TIME) SELECT SEQ_GATE_RETRY_QUEUE.NEXTVAL, t.* FROM (
SELECT #{item.orderNo,jdbcType=VARCHAR}, #{item.txnDate,jdbcType=VARCHAR}, #{item.thirdUserId,jdbcType=VARCHAR}, #{item.cardId,jdbcType=VARCHAR}, 'PENDING', #{item.retryCount,jdbcType=INTEGER}, #{item.maxRetries,jdbcType=INTEGER} FROM DUAL WHERE NOT EXISTS ( SELECT 1 FROM GATE_RETRY_QUEUE q WHERE q.ORDER_NO = #{item.orderNo,jdbcType=VARCHAR} AND q.TXX_DATE = #{item.txnDate,jdbcType=VARCHAR} )
) t
